import future.keywords.in

insecure_protocols := {"http", "udp", "ftp", "smtp"}
integrity_disable_attrs := {"validate_certs", "gpgcheck", "disable_checksum", "no_integrity_check"}
integrity_enable_attrs := {"checksum", "validate_certs", "gpgcheck"}
